'use strict';
(function(){
  let modal=null,busy=false,question=null,lastResult=null,retrying=false,memoryPending=null,memoryOwner=null,loadError='';
  const hud=document.createElement('div');hud.id='learningEnergy';hud.hidden=true;hud.innerHTML='<button id="learningQuestionBtn" aria-label="ตอบคำถามเติมพลัง"><span class="learning-energy-icon" aria-hidden="true">ϟ</span><span id="learningEnergyText"></span><span class="learning-energy-action">เติมพลัง</span></button><meter id="learningEnergyMeter" min="0" max="3000" aria-label="พลังงานสำหรับเดิน"></meter>';document.body.appendChild(hud);
  const key=()=>education.session?'rift.playAnswer:'+education.session.playerId:null;
  const pending=()=>{const memory=memoryOwner===key()?memoryPending:null;try{return JSON.parse(localStorage.getItem(key())||'null')||memory;}catch{return memory;}};
  function clear(){memoryPending=null;try{localStorage.removeItem(key());}catch{}}
  function active(){return education.session&&education.details?.phase==='play'&&education.details?.energyQuestions;}
  function update(resources){if(!resources)return;if(education.details?.paused&&modal?.open)modal.close();if(education.details)education.details.resources=resources;const visible=active()&&education.details.activity!=='snow'&&!document.body.classList.contains('education-open');hud.hidden=!visible;if(!visible)return;$('learningEnergyText').textContent=resources.energy>0?resources.energy+' / 3000':'พลังหมด';$('learningQuestionBtn').setAttribute('aria-label','ตอบคำถามเติมพลัง · พลังงาน '+resources.energy+' จาก 3000');$('learningEnergyMeter').value=resources.energy;hud.classList.toggle('empty',resources.energy<=0);}
  function render(){if(!modal)return;if(question&&lastResult?.cursor!==question.cursor)lastResult=null;const d=education.details,esc=escapeText;modal.innerHTML='<div class="play-question-heading"><h2>ตอบคำถามเติมพลัง</h2><button id="closePlayQuestion" aria-label="ปิดคำถามและกลับเข้าสนาม">กลับเข้าสนาม</button></div><p class="lesson-note">ขณะตอบ ตัวละครจะหยุดเดิน · '+(d.activity==='snow'?'ตอบถูกได้พลังงาน 1,000 และหิมะ 6 ลูก':'ตอบถูกได้พลังงาน 1,000')+' · สะสมพลังงานได้ 3,000</p><div id="playQuestionStatus" role="status" aria-live="polite"></div>'+(!question?(loadError?'<p>'+esc(loadError)+'</p><button id="retryPlayQuestion">ลองโหลดคำถามใหม่</button>':'<p>กำลังโหลดคำถาม…</p>'):`<h3>${esc(question.question.prompt)}</h3>${RiftClassTools.imageHTML(question.question,esc)}<div class="quiz-options">${question.question.options.map((v,i)=>`<button data-play-choice="${i}" ${busy||lastResult?'disabled':''}><b>${String.fromCharCode(65+i)}</b>${esc(v)}</button>`).join('')}</div>${lastResult?`<div class="answer-feedback ${lastResult.correct?'correct':'incorrect'}"><b>${lastResult.correct?'ตอบถูก · เติมพลังแล้ว':'ยังไม่ถูก · ลองทบทวนคำอธิบาย'} · เฉลย ${esc(question.question.options[lastResult.feedback.correct])}</b><p>${esc(lastResult.feedback.explanation||'ครูยังไม่ได้เพิ่มคำอธิบาย')}</p><button id="nextPlayQuestion">ตอบข้อถัดไป</button></div>`:''}`);modal.querySelector('#closePlayQuestion').onclick=()=>modal.close();modal.querySelectorAll('[data-play-choice]').forEach(b=>b.onclick=()=>submit(Number(b.dataset.playChoice)));const retry=modal.querySelector('#retryPlayQuestion');if(retry)retry.onclick=load;const next=modal.querySelector('#nextPlayQuestion');if(next)next.onclick=load;}
  function status(s){const el=modal?.querySelector('#playQuestionStatus');if(el)el.textContent=s;}
  async function load(){if(busy||!active())return;busy=true;lastResult=null;loadError='';question=null;render();try{await flush();lastResult=null;question=await lessonRequest(`classes/${education.session.code}/play-question`);update(question.resources);}catch(e){loadError=e.message;}finally{busy=false;render();}}
  async function submit(choice){if(busy||!question||lastResult)return;busy=true;const value={cursor:question.cursor,questionId:question.question.id,answer:choice};memoryPending=value;memoryOwner=key();try{localStorage.setItem(key(),JSON.stringify(value));}catch{}render();try{await send(value);}catch(e){status(e.message+(e.status?'':' · เก็บคำตอบไว้แล้ว จะลองส่งเมื่อเชื่อมต่อ'));}finally{busy=false;if(lastResult)render();else modal?.querySelectorAll('[data-play-choice]').forEach(b=>b.disabled=!!pending());}}
  async function send(value){const session=education.session;if(!session)return;const result=await lessonRequest(`classes/${session.code}/play-answer`,'POST',value);if(education.session!==session)return;clear();lastResult=result;update(result.resources);}
  async function flush(){if(retrying||!active()||education.details.paused)return;const value=pending();if(!value)return;retrying=true;try{await send(value);if(modal?.open&&lastResult&&question)render();}catch(e){if([400,401,404].includes(e.status)||e.status===409&&!education.details.paused){clear();status('ช่วงคำถามเปลี่ยนแล้ว เปิดคำถามใหม่');}else status(e.message+' · รอส่งอีกครั้ง');}finally{retrying=false;}}
  function open(){if(!active()||education.details.paused)return;if(modal?.open)return;modal=document.createElement('dialog');modal.className='lesson-card play-question-dialog';document.body.appendChild(modal);modal.addEventListener('close',()=>{modal.remove();modal=null;question=null;lastResult=null;loadError='';});keys.clear();joystick={x:0,y:0};if(game?.player)game.player.destination=null;modal.showModal();void load();}
  $('learningQuestionBtn').onclick=open;
  window.RiftLearningPlay={open,update,flush,studying:()=>!!modal?.open,stop:()=>{if(modal?.open)modal.close();hud.hidden=true;},pending};
  window.addEventListener('online',()=>void flush());
  const oldLocal=localInput;localInput=function(){const b=oldLocal();if(net.session?.classroom&&education.details?.energyQuestions){const studying=!!modal?.open;b.studying=studying;b.moving=!studying&&!document.body.classList.contains('education-open')&&!!game?.player?.destination;if(studying){b.move={x:0,y:0};b.attack=false;b.commands=[];} }return b;};
  const beforeBlocked=controlsBlocked;controlsBlocked=function(){return beforeBlocked()||!!modal?.open;};
  const oldMove=move;move=function(e,x,y,dt){if(game?.education&&education.details?.energyQuestions&&e.clientId&&(e.lessonEnergy??0)<=0)return;return oldMove(e,x,y,dt);};
  const oldUpdate=update;update=function(dt){if(game?.education&&education.details?.energyQuestions&&net.session?.host){for(const e of game.entities.filter(e=>e.clientId)){if(e.player&&modal?.open){e.destination=null;const savedKeys=new Set(keys);keys.clear();const savedStick=joystick;joystick={x:0,y:0};oldUpdate(dt);for(const k of savedKeys)keys.add(k);joystick=savedStick;return;}}}return oldUpdate(dt);};
})();
